function writePacketText(text, target, offset) {
  const bytes = new TextEncoder().encode(text);
  const written = Math.min(bytes.length, target.length - offset);
  target.set(bytes.subarray(0, written), offset);
  return {read: written, written};
}
module.exports = { writePacketText };

