const test = require('node:test');
const assert = require('node:assert/strict');
const { writePacketText } = require('../src/packet-text.cjs');

test("UTF-16 read count differs from UTF-8 written count", () => {
  const target = new Uint8Array(9).fill(165);
  assert.deepEqual(writePacketText('A😀B', target, 3), {read: 4, written: 6});
  assert.deepEqual(Array.from(target), [165,165,165,65,240,159,152,128,66]);
});

test("a short destination never writes part of the next code point", () => {
  const target = new Uint8Array(6).fill(165);
  assert.deepEqual(writePacketText('A😀B', target, 2), {read: 1, written: 1});
  assert.deepEqual(Array.from(target), [165,165,65,165,165,165]);
  assert.deepEqual(writePacketText('中', new Uint8Array(2), 0), {read: 0, written: 0});
});

test("no terminator is added and zero space makes no progress", () => {
  const target = new Uint8Array(5).fill(165);
  assert.deepEqual(writePacketText('A\u0000B', target, 1), {read: 3, written: 3});
  assert.deepEqual(Array.from(target), [165,65,0,66,165]);
  assert.deepEqual(writePacketText('oak', target, target.length), {read: 0, written: 0});
  assert.deepEqual(writePacketText('', target, 0), {read: 0, written: 0});
});

